#Requires -Version 5.1
<#
Read-only Windows 11 configuration audit, producing a CSV report.
Run locally as Administrator in PowerShell.

Covers Windows 11 workstations that are domain joined or standalone (workgroup or Microsoft Entra joined).
BitLocker-related checks are reported under the area 'BitLocker profile (BL)' so they can be filtered separately.

Parameter -OutputPath
    CSV path in an existing directory. When omitted, a timestamped filename is created in the current directory.

.EXAMPLE
    & '.\Audit-Windows-11.ps1' -OutputPath '.\audit.csv'
#>

param(
    [string]$OutputPath = (Join-Path (Get-Location).Path ('Windows-11-Audit-{0}-{1}.csv' -f $env:COMPUTERNAME, (Get-Date -Format 'yyyyMMdd-HHmmss-fff')))
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
if ($env:OS -ne 'Windows_NT') { throw 'Run this script locally on Windows 11.' }
if (-not [Environment]::Is64BitProcess) { throw 'Use a 64-bit PowerShell process.' }
$os = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
$computer = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop
$osBuild = 0
if (-not [int]::TryParse([string]$os.BuildNumber, [ref]$osBuild)) { $osBuild = 0 }
if ([int]$os.ProductType -ne 1 -or $osBuild -lt 22000) {
    throw ('This audit targets Windows 11 (client build 22000 or later). Detected: {0} (build {1})' -f $os.Caption, $os.BuildNumber)
}
$role = 'WS'
$joined = [bool]$computer.PartOfDomain
$membership = if ($joined) { 'DomainJoinedMember' } else { 'Workgroup' }
$principal = New-Object Security.Principal.WindowsPrincipal ([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    throw 'Run PowerShell as Administrator so that security-policy queries can be read.'
}
$csvPath = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($OutputPath)
if ([IO.Path]::GetExtension($csvPath) -ine '.csv') { throw 'OutputPath must end in .csv.' }
if (-not [IO.Directory]::Exists([IO.Path]::GetDirectoryName($csvPath))) { throw 'The output directory must already exist.' }
if ([IO.File]::Exists($csvPath) -or [IO.Directory]::Exists($csvPath)) { throw 'OutputPath already exists. Choose a new filename.' }
$runUtc = [DateTime]::UtcNow.ToString('o')
$nativeError = ''
try {
    if (-not ('Windows11AuditR1.Native' -as [type])) {
        Add-Type -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Runtime.InteropServices;
using System.Security.Principal;
namespace Windows11AuditR1 {
    public static class Native {
        [StructLayout(LayoutKind.Sequential)] struct LsaObjectAttributes {
            public uint Length; public IntPtr RootDirectory, ObjectName;
            public uint Attributes; public IntPtr SecurityDescriptor, SecurityQualityOfService;
        }
        [StructLayout(LayoutKind.Sequential)] struct LsaString {
            public ushort Length, MaximumLength; public IntPtr Buffer;
        }
        [StructLayout(LayoutKind.Sequential)] struct AuditInfo {
            public Guid Subcategory; public uint Flags; public Guid Category;
        }
        [StructLayout(LayoutKind.Sequential)] struct Modals0 {
            public uint MinLength, MaxAge, MinAge, ForceLogoff, History;
        }
        [StructLayout(LayoutKind.Sequential)] struct Modals3 {
            public uint Duration, ObservationWindow, Threshold;
        }
        [StructLayout(LayoutKind.Sequential)] struct Modals2 {
            public IntPtr Name, Sid;
        }
        [StructLayout(LayoutKind.Sequential)] struct Luid {
            public uint LowPart; public int HighPart;
        }
        [StructLayout(LayoutKind.Sequential)] struct TokenPrivileges {
            public uint Count; public Luid Luid; public uint Attributes;
        }
        [DllImport("kernel32.dll")] static extern IntPtr GetCurrentProcess();
        [DllImport("kernel32.dll")] static extern IntPtr GetCurrentThread();
        [DllImport("kernel32.dll", SetLastError=true)]
        [return: MarshalAs(UnmanagedType.Bool)] static extern bool CloseHandle(IntPtr handle);
        [DllImport("advapi32.dll", SetLastError=true)]
        [return: MarshalAs(UnmanagedType.Bool)] static extern bool OpenProcessToken(IntPtr process, uint access, out IntPtr token);
        [DllImport("advapi32.dll", SetLastError=true)]
        [return: MarshalAs(UnmanagedType.Bool)] static extern bool OpenThreadToken(IntPtr thread, uint access, [MarshalAs(UnmanagedType.Bool)] bool asSelf, out IntPtr token);
        [DllImport("advapi32.dll", CharSet=CharSet.Unicode, SetLastError=true)]
        [return: MarshalAs(UnmanagedType.Bool)] static extern bool LookupPrivilegeValue(string system, string name, out Luid luid);
        [DllImport("advapi32.dll", SetLastError=true, EntryPoint="AdjustTokenPrivileges")]
        [return: MarshalAs(UnmanagedType.Bool)] static extern bool EnablePrivilege(IntPtr token, [MarshalAs(UnmanagedType.Bool)] bool disableAll, ref TokenPrivileges desired, uint length, out TokenPrivileges previous, out uint required);
        [DllImport("advapi32.dll", SetLastError=true, EntryPoint="AdjustTokenPrivileges")]
        [return: MarshalAs(UnmanagedType.Bool)] static extern bool RestorePrivilege(IntPtr token, [MarshalAs(UnmanagedType.Bool)] bool disableAll, ref TokenPrivileges previous, uint length, IntPtr ignoredPrevious, IntPtr ignoredLength);
        [DllImport("advapi32.dll")] static extern uint LsaOpenPolicy(IntPtr system, ref LsaObjectAttributes attributes, uint access, out IntPtr handle);
        [DllImport("advapi32.dll")] static extern uint LsaEnumerateAccountsWithUserRight(IntPtr handle, ref LsaString right, out IntPtr buffer, out uint count);
        [DllImport("advapi32.dll")] static extern uint LsaClose(IntPtr handle);
        [DllImport("advapi32.dll")] static extern uint LsaFreeMemory(IntPtr memory);
        [DllImport("advapi32.dll")] static extern uint LsaNtStatusToWinError(uint status);
        [DllImport("advapi32.dll", SetLastError=true)]
        [return: MarshalAs(UnmanagedType.U1)]
        static extern bool AuditQuerySystemPolicy([In] Guid[] guids, uint count, out IntPtr result);
        [DllImport("advapi32.dll")] static extern void AuditFree(IntPtr result);
        [DllImport("netapi32.dll", CharSet=CharSet.Unicode)] static extern uint NetUserModalsGet(string server, uint level, out IntPtr buffer);
        [DllImport("netapi32.dll")] static extern uint NetApiBufferFree(IntPtr buffer);
        static void Check(uint status) { if (status != 0) throw new Win32Exception((int)status); }
        public static string[] Rights(string name) {
            IntPtr handle=IntPtr.Zero, buffer=IntPtr.Zero;
            LsaObjectAttributes attributes=new LsaObjectAttributes();
            attributes.Length=(uint)Marshal.SizeOf(typeof(LsaObjectAttributes));
            LsaString right=new LsaString(); right.Buffer=Marshal.StringToHGlobalUni(name);
            right.Length=checked((ushort)(name.Length*2)); right.MaximumLength=checked((ushort)(right.Length+2));
            try {
                Check(LsaNtStatusToWinError(LsaOpenPolicy(IntPtr.Zero, ref attributes, 0x801, out handle)));
                uint count; uint status=LsaEnumerateAccountsWithUserRight(handle, ref right, out buffer, out count);
                if (status==0x8000001A) return new string[0];
                Check(LsaNtStatusToWinError(status));
                List<string> sids=new List<string>();
                for (uint i=0;i<count;i++) {
                    IntPtr sid=Marshal.ReadIntPtr(buffer, checked((int)i*IntPtr.Size));
                    sids.Add(new SecurityIdentifier(sid).Value);
                }
                return sids.ToArray();
            } finally {
                if (buffer!=IntPtr.Zero) LsaFreeMemory(buffer);
                if (handle!=IntPtr.Zero) LsaClose(handle);
                Marshal.FreeHGlobal(right.Buffer);
            }
        }
        static uint ReadAudit(Guid id) {
            IntPtr buffer=IntPtr.Zero;
            try {
                if (!AuditQuerySystemPolicy(new Guid[]{id},1,out buffer)) throw new Win32Exception(Marshal.GetLastWin32Error());
                return ((AuditInfo)Marshal.PtrToStructure(buffer,typeof(AuditInfo))).Flags;
            } finally { if(buffer!=IntPtr.Zero) AuditFree(buffer); }
        }
        public static uint Audit(string id) {
            Guid guid=new Guid(id);
            try { return ReadAudit(guid); }
            catch (Win32Exception ex) { if(ex.NativeErrorCode!=5 && ex.NativeErrorCode!=1314) throw; }
            IntPtr token=IntPtr.Zero;
            TokenPrivileges previous=new TokenPrivileges();
            bool adjusted=false;
            try {
                if(!OpenThreadToken(GetCurrentThread(),0x28,true,out token)) {
                    int error=Marshal.GetLastWin32Error();
                    if(error!=1008) throw new Win32Exception(error);
                    if(!OpenProcessToken(GetCurrentProcess(),0x28,out token)) throw new Win32Exception(Marshal.GetLastWin32Error());
                }
                Luid luid;
                if(!LookupPrivilegeValue(null,"SeSecurityPrivilege",out luid)) throw new Win32Exception(Marshal.GetLastWin32Error());
                TokenPrivileges desired=new TokenPrivileges();
                desired.Count=1; desired.Luid=luid; desired.Attributes=2;
                uint required;
                if(!EnablePrivilege(token,false,ref desired,(uint)Marshal.SizeOf(typeof(TokenPrivileges)),out previous,out required)) throw new Win32Exception(Marshal.GetLastWin32Error());
                int enableError=Marshal.GetLastWin32Error();
                adjusted=previous.Count>0;
                if(enableError!=0) throw new Win32Exception(enableError);
                return ReadAudit(guid);
            } finally {
                int restoreError=0;
                if(adjusted) {
                    bool restored=RestorePrivilege(token,false,ref previous,0,IntPtr.Zero,IntPtr.Zero);
                    restoreError=Marshal.GetLastWin32Error();
                    if(!restored && restoreError==0) restoreError=31;
                }
                if(token!=IntPtr.Zero) CloseHandle(token);
                if(restoreError!=0) throw new Win32Exception(restoreError,"Could not restore the previous audit-query token privilege state.");
            }
        }
        public static Dictionary<string,double> PasswordPolicy() {
            Dictionary<string,double> values=new Dictionary<string,double>();
            IntPtr buffer=IntPtr.Zero;
            try {
                Check(NetUserModalsGet(null,0,out buffer));
                Modals0 m=(Modals0)Marshal.PtrToStructure(buffer,typeof(Modals0));
                values["MinLength"]=m.MinLength; values["History"]=m.History;
                values["MaxAgeDays"]=m.MaxAge==UInt32.MaxValue ? Double.PositiveInfinity : m.MaxAge/86400.0;
                values["MinAgeDays"]=m.MinAge/86400.0;
            } finally { if(buffer!=IntPtr.Zero) NetApiBufferFree(buffer); }
            return values;
        }
        public static Dictionary<string,double> LockoutPolicy() {
            Dictionary<string,double> values=new Dictionary<string,double>();
            IntPtr buffer=IntPtr.Zero;
            try {
                Check(NetUserModalsGet(null,3,out buffer));
                Modals3 m=(Modals3)Marshal.PtrToStructure(buffer,typeof(Modals3));
                values["LockoutMinutes"]=m.Duration==UInt32.MaxValue ? Double.PositiveInfinity : m.Duration/60.0;
                values["ResetMinutes"]=m.ObservationWindow/60.0; values["Threshold"]=m.Threshold;
            } finally { if(buffer!=IntPtr.Zero) NetApiBufferFree(buffer); }
            return values;
        }
        public static string AccountDomainSid() {
            IntPtr buffer=IntPtr.Zero;
            try {
                Check(NetUserModalsGet(null,2,out buffer));
                Modals2 m=(Modals2)Marshal.PtrToStructure(buffer,typeof(Modals2));
                return new SecurityIdentifier(m.Sid).Value;
            } finally { if(buffer!=IntPtr.Zero) NetApiBufferFree(buffer); }
        }
    }
}
'@ -ErrorAction Stop | Out-Null
    }
} catch { $nativeError = $_.Exception.Message }

$rows = New-Object 'System.Collections.Generic.List[object]'
function Add-Result {
    param($Control, [string]$Status, [string]$Actual='', [string]$Evidence='', [string]$Notes='', [string]$Scope='Computer')
    $rows.Add([pscustomobject][ordered]@{
        ComputerName=$env:COMPUTERNAME; TimestampUTC=$runUtc; OS=$os.Caption; Build=$os.BuildNumber
        Role=$role; Membership=$membership; DomainJoined=$joined; ScriptRevision='W11-1'
        ControlId=$Control.Id; Recommendation=$Control.Title; Assessment=$Control.Assessment
        Scope=$Scope; Status=$Status; Expected=(Get-ExpectedDisplay $Control)
        Actual=$Actual; Evidence=$Evidence; Notes=$Notes
    }) | Out-Null
}


function Get-RegistryEvidence {
    param([string]$Hive, [string]$Key, [string]$Name)
    $base = $null; $sub = $null
    try {
        $h = if ($Hive -eq 'HKU') { [Microsoft.Win32.RegistryHive]::Users } else { [Microsoft.Win32.RegistryHive]::LocalMachine }
        $base = [Microsoft.Win32.RegistryKey]::OpenBaseKey($h, [Microsoft.Win32.RegistryView]::Registry64)
        $sub = $base.OpenSubKey($Key, $false)
        if ($null -eq $sub -or $sub.GetValueNames() -inotcontains $Name) {
            return [pscustomobject]@{Exists=$false; Value=$null; Type='Absent'}
        }
        return [pscustomobject]@{Exists=$true; Value=$sub.GetValue($Name, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames); Type=$sub.GetValueKind($Name).ToString()}
    } finally {
        if ($null -ne $sub) { $sub.Dispose() }; if ($null -ne $base) { $base.Dispose() }
    }
}
function Format-Evidence {
    param($Value)
    if ($null -eq $Value) { return '<absent>' }
    if ($Value -is [array]) { return (($Value | ForEach-Object { [string]$_ }) -join ' | ') }
    return [string]$Value
}
function Test-Value {
    param($Actual, [string]$Operator, [object[]]$Expected)
    switch ($Operator) {
        'Equals' { return ([string]$Actual -ieq [string]$Expected[0]) }
        'OneOf' { return (@($Expected | Where-Object { [string]$_ -ieq [string]$Actual }).Count -gt 0) }
        'NotOneOf' { return (@($Expected | Where-Object { [string]$_ -ieq [string]$Actual }).Count -eq 0) }
        'AtLeast' { return ([double]$Actual -ge [double]$Expected[0]) }
        'Range' { return ([double]$Actual -ge [double]$Expected[0] -and [double]$Actual -le [double]$Expected[1]) }
        'SetEquals' {
            $aa = @($Actual | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { ([string]$_).Trim().ToLowerInvariant() } | Sort-Object -Unique)
            $ee = @($Expected | ForEach-Object { ([string]$_).Trim().ToLowerInvariant() } | Sort-Object -Unique)
            return (($aa -join "`n") -ceq ($ee -join "`n"))
        }
        'Contains' {
            foreach ($item in $Expected) { if (@($Actual) -inotcontains $item) { return $false } }
            return $true
        }
        'Empty' { return (@($Actual | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }).Count -eq 0) }
        'LogPath' { return (-not [string]::IsNullOrWhiteSpace([string]$Actual) -and [string]$Actual -match '\\[^\\]+\.log$') }
        'UNC' {
            $pairs = @{}
            foreach ($part in ([string]$Actual -split ',')) {
                $kv = $part.Trim() -split '=',2
                if ($kv.Count -ne 2 -or $pairs.ContainsKey($kv[0].Trim())) { return $false }
                $pairs[$kv[0].Trim()] = $kv[1].Trim()
            }
            foreach ($field in 'RequireMutualAuthentication','RequireIntegrity','RequirePrivacy') {
                if (-not $pairs.ContainsKey($field) -or $pairs[$field] -ne '1') { return $false }
            }
            return $true
        }
        'AuditIncludes' { return (([uint32]$Actual -band [uint32]$Expected[0]) -eq [uint32]$Expected[0]) }
        'AuditEquals' { return (([uint32]$Actual -band 3) -eq [uint32]$Expected[0]) }
        default { throw "Unimplemented comparison: $Operator" }
    }
}
function Resolve-PrincipalSid {
    param([string]$Name)
    $fixed = @{
        'Administrators'='S-1-5-32-544'; 'Authenticated Users'='S-1-5-11'; 'Users'='S-1-5-32-545'
        'ENTERPRISE DOMAIN CONTROLLERS'='S-1-5-9'; 'LOCAL SERVICE'='S-1-5-19'
        'NETWORK SERVICE'='S-1-5-20'; 'SERVICE'='S-1-5-6'; 'Guests'='S-1-5-32-546'
        'Remote Desktop Users'='S-1-5-32-555'; 'Local account'='S-1-5-113'
        'Local account and member of Administrators group'='S-1-5-114'
        'NT VIRTUAL MACHINE\Virtual Machines'='S-1-5-83-0'
        'Window Manager\Window Manager Group'='S-1-5-90-0'; 'IIS_IUSRS'='S-1-5-32-568'
    }
    if ($fixed.ContainsKey($Name)) { return $fixed[$Name] }
    $account = New-Object Security.Principal.NTAccount ($Name)
    return $account.Translate([Security.Principal.SecurityIdentifier]).Value
}
function Test-RegistryKeyExists {
    param([string]$Key)
    $base = $null; $sub = $null
    try {
        $base = [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine, [Microsoft.Win32.RegistryView]::Registry64)
        $sub = $base.OpenSubKey($Key, $false)
        return ($null -ne $sub)
    } finally {
        if ($null -ne $sub) { $sub.Dispose() }; if ($null -ne $base) { $base.Dispose() }
    }
}
function Get-RegistryKeyData {
    param([string]$Key)
    $base = $null; $sub = $null
    try {
        $base = [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine, [Microsoft.Win32.RegistryView]::Registry64)
        $sub = $base.OpenSubKey($Key, $false)
        if ($null -eq $sub) { return [pscustomobject]@{Exists=$false; Data=@()} }
        $data = New-Object 'System.Collections.Generic.List[string]'
        foreach ($valueName in $sub.GetValueNames()) {
            foreach ($entry in @($sub.GetValue($valueName, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames))) {
                if (-not [string]::IsNullOrWhiteSpace([string]$entry)) { $data.Add(([string]$entry).Trim()) }
            }
        }
        return [pscustomobject]@{Exists=$true; Data=@($data.ToArray())}
    } finally {
        if ($null -ne $sub) { $sub.Dispose() }; if ($null -ne $base) { $base.Dispose() }
    }
}
$featureCache = @{}
function Get-FeatureInstalled {
    # Windows 11 has no Get-WindowsFeature. Components are detected read-only from service registration
    # or from the Win32_OptionalFeature class (InstallState 1 = enabled).
    param([string]$Name)
    if (-not $featureCache.ContainsKey($Name)) {
        $installed = $false
        switch ($Name) {
            'HyperV' {
                $installed = (Test-RegistryKeyExists 'SYSTEM\CurrentControlSet\Services\vmms') -or (Test-RegistryKeyExists 'SYSTEM\CurrentControlSet\Services\vmcompute')
            }
            'IIS' { $installed = Test-RegistryKeyExists 'SYSTEM\CurrentControlSet\Services\W3SVC' }
            'WDAG' {
                $features = @(Get-CimInstance -ClassName Win32_OptionalFeature -Filter "Name='Windows-Defender-ApplicationGuard'" -ErrorAction Stop)
                $installed = (@($features | Where-Object { [int]$_.InstallState -eq 1 }).Count -gt 0)
            }
            default { throw "Unknown component condition: $Name" }
        }
        $featureCache[$Name] = [bool]$installed
    }
    return $featureCache[$Name]
}
function Get-MissingRegistryStatus {
    param([string]$Operator)
    if ($Operator -eq 'Absent') { return 'Pass' }
    return 'Unknown'
}
function Get-ExpectedDisplay {
    param($Control)
    if ($Control.Operator -eq 'SetEquals' -and @($Control.Values).Count -eq 0) { return 'SetEquals: (No One)' }
    if ($Control.Operator -eq 'Absent') { return 'Value must be absent' }
    if ($Control.Operator) { return ('{0}: {1}' -f $Control.Operator, (Format-Evidence $Control.Values)) }
    return 'Manual confirmation per recommendation'
}
function ConvertTo-SafeCsvCell {
    param($Value)
    if ($Value -isnot [string]) { return $Value }
    if ($Value -match '^\s*[\t\r\n]') { return "'"+$Value }
    if ($Value -match '^\s*[\uFF1D\uFF0B\uFF0D\uFF20]') { return "'"+$Value }
    if ($Value -match '^\s*[=+@]') { return "'"+$Value }
    if ($Value -match '^\s*-') {
        $number = [double]0
        $isNumber = [double]::TryParse($Value, [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture, [ref]$number)
        if (-not $isNumber -or [double]::IsNaN($number) -or [double]::IsInfinity($number)) { return "'"+$Value }
    }
    return $Value
}
