'@ | ConvertFrom-Json
function Expand-RoleField {
    param($Field)
    if ($Field -is [string]) {
        return [pscustomobject]@{ Workgroup = $Field; DomainJoinedMember = $Field }
    }
    if ($null -ne $Field.PSObject.Properties['Shared']) {
        return [pscustomobject]@{ Workgroup = $Field.Workgroup; DomainJoinedMember = $Field.Shared }
    }
    return [pscustomobject]@{ Workgroup = $Field.Workgroup; DomainJoinedMember = $Field.DomainJoinedMember }
}
$reportMetadata = foreach ($entry in $reportCatalogue) {
    $steps = Expand-RoleField $entry.Steps
    $ctype = Expand-RoleField $entry.CheckType
    $rat   = Expand-RoleField $entry.Rationale
    $imp   = Expand-RoleField $entry.Impact
    [pscustomobject]@{
        Id                 = $entry.Id
        Area               = $entry.Area
        AuditCheck         = $entry.AuditCheck
        Expected           = $entry.Expected
        Workgroup          = [pscustomobject]@{ Steps = $steps.Workgroup;          CheckType = $ctype.Workgroup;          Rationale = $rat.Workgroup;          Impact = $imp.Workgroup }
        DomainJoinedMember = [pscustomobject]@{ Steps = $steps.DomainJoinedMember; CheckType = $ctype.DomainJoinedMember; Rationale = $rat.DomainJoinedMember; Impact = $imp.DomainJoinedMember }
    }
}
$reportById = @{}
foreach ($item in $reportMetadata) { $reportById[$item.Id] = $item }
$knownSidNames = @{
    'S-1-1-0'='Everyone'; 'S-1-5-2'='NT AUTHORITY\NETWORK'; 'S-1-5-4'='NT AUTHORITY\INTERACTIVE'
    'S-1-5-6'='NT AUTHORITY\SERVICE'; 'S-1-5-9'='NT AUTHORITY\ENTERPRISE DOMAIN CONTROLLERS'
    'S-1-5-11'='NT AUTHORITY\Authenticated Users'; 'S-1-5-18'='NT AUTHORITY\SYSTEM'
    'S-1-5-19'='NT AUTHORITY\LOCAL SERVICE'; 'S-1-5-20'='NT AUTHORITY\NETWORK SERVICE'
    'S-1-5-32-544'='BUILTIN\Administrators'; 'S-1-5-32-545'='BUILTIN\Users'
    'S-1-5-32-546'='BUILTIN\Guests'; 'S-1-5-32-547'='BUILTIN\Power Users'
    'S-1-5-32-548'='BUILTIN\Account Operators'; 'S-1-5-32-549'='BUILTIN\Server Operators'
    'S-1-5-32-550'='BUILTIN\Print Operators'; 'S-1-5-32-551'='BUILTIN\Backup Operators'
    'S-1-5-32-552'='BUILTIN\Replicator'; 'S-1-5-32-554'='BUILTIN\Pre-Windows 2000 Compatible Access'
    'S-1-5-32-555'='BUILTIN\Remote Desktop Users'; 'S-1-5-32-556'='BUILTIN\Network Configuration Operators'
    'S-1-5-32-558'='BUILTIN\Performance Monitor Users'; 'S-1-5-32-559'='BUILTIN\Performance Log Users'
    'S-1-5-32-568'='BUILTIN\IIS_IUSRS'; 'S-1-5-32-569'='BUILTIN\Cryptographic Operators'
    'S-1-5-32-573'='BUILTIN\Event Log Readers'; 'S-1-5-32-574'='BUILTIN\Certificate Service DCOM Access'
    'S-1-5-32-578'='BUILTIN\Hyper-V Administrators'; 'S-1-5-32-580'='BUILTIN\Remote Management Users'
    'S-1-5-83-0'='NT VIRTUAL MACHINE\Virtual Machines'; 'S-1-5-90-0'='Window Manager\Window Manager Group'
    'S-1-5-32-583'='BUILTIN\Device Owners'; 'S-1-5-32-581'='BUILTIN\System Managed Accounts Group'
    'S-1-5-113'='NT AUTHORITY\Local account'; 'S-1-5-114'='NT AUTHORITY\Local account and member of Administrators group'
}
function Format-ReportActual {
    param([string]$Value)
    $parts = foreach ($part in ($Value -split ' \| ')) {
        $sid = $part.Trim()
        if ($knownSidNames.ContainsKey($sid)) { '{0} ({1})' -f $sid, $knownSidNames[$sid] }
        else { $part }
    }
    return ($parts -join ' | ')
}
function ConvertTo-SpreadsheetRow {
    param($Row)
    $item = $reportById[$Row.ControlId]
    if ($null -eq $item) { throw 'No reporting metadata was found for an audit check.' }
    $text = $item.($Row.Membership)
    $steps = $text.Steps.Replace('{HOST}', [string]$Row.ComputerName)
    if ($Row.Scope -match '^S-1-') { $steps = $steps.Replace('[USER SID]', [string]$Row.Scope) }
    $interpretation = switch ($Row.Status) {
        'Pass' { 'Pass: observed configuration met the tested requirement.' }
        'Fail' { 'Fail: observed configuration did not meet the tested requirement.' }
        'Unknown' { 'Unknown: configuration could not be established; this result is unresolved.' }
        'Error' { 'Error: the query failed; this result is unresolved. See Review Notes.' }
        'ManualReview' { 'ManualReview: confirmation against approved policy is required; this result is unresolved.' }
        'NotApplicable' { 'NotApplicable: this check does not apply to this system.' }
        default { throw ('Unexpected audit status: '+$Row.Status) }
    }
    $notes = New-Object 'System.Collections.Generic.List[string]'
    if ($Row.Notes) { $notes.Add([string]$Row.Notes) }
    $notes.Add(('Collected (UTC): {0}.' -f $Row.TimestampUTC))
    if ($Row.Scope -ne 'Computer') { $notes.Add(('User scope: {0}.' -f $Row.Scope)) }
    return [pscustomobject][ordered]@{
        'Hostname'=$Row.ComputerName
        'Membership'=$Row.Membership
        'Area'=$item.Area
        'Audit Check'=$item.AuditCheck
        'Recommended Value / Threshold'=$item.Expected
        'Audit Command/Steps'=$steps
        'Result During Audit'=(Format-ReportActual ([string]$Row.Actual))
        'Result Interpretation'=$interpretation
        'Check Type'=$text.CheckType
        'Review Notes'=($notes -join ' ')
        'Rationale'=$text.Rationale
        'Potential impact if actioned'=$text.Impact
        'OperatingSystem'=$Row.OS
        'Build'=$Row.Build
    }
}
function Get-AreaSummary {
    param([object[]]$Rows)
    $controls = foreach ($group in ($Rows | Group-Object ControlId)) {
        $statuses = @($group.Group | ForEach-Object { $_.Status })
        $status = if ($statuses -contains 'Fail') { 'Fail' }
                  elseif (@($statuses | Where-Object { $_ -in 'Unknown','Error','ManualReview' }).Count -gt 0) { 'Unresolved' }
                  elseif ($statuses -contains 'Pass') { 'Pass' }
                  else { 'NotApplicable' }
        [pscustomobject]@{Area=$reportById[$group.Name].Area; Status=$status}
    }
    foreach ($group in ($controls | Group-Object Area | Sort-Object Name)) {
        $pass = @($group.Group | Where-Object { $_.Status -eq 'Pass' }).Count
        $fail = @($group.Group | Where-Object { $_.Status -eq 'Fail' }).Count
        $unresolved = @($group.Group | Where-Object { $_.Status -eq 'Unresolved' }).Count
        $na = @($group.Group | Where-Object { $_.Status -eq 'NotApplicable' }).Count
        $percent = if ($pass+$fail -gt 0) { 100.0*$pass/($pass+$fail) } else { $null }
        [pscustomobject]@{Area=$group.Name; Pass=$pass; Fail=$fail; Unresolved=$unresolved; NotApplicable=$na; AssessedPassPercent=$percent}
    }
}

$passwordValues = $null; $passwordError = ''; $lockValues = $null; $lockError = ''
if (-not $nativeError) {
    try { $passwordValues = [Windows11AuditR1.Native]::PasswordPolicy() } catch { $passwordError = $_.Exception.Message }
    try { $lockValues = [Windows11AuditR1.Native]::LockoutPolicy() } catch { $lockError = $_.Exception.Message }
}
$userTargets = @(); $userEnumerationError = '' 
try {
    $ubase = [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::Users, [Microsoft.Win32.RegistryView]::Registry64)
    try { $loadedSids = @($ubase.GetSubKeyNames() | Where-Object { $_ -match '^S-1-(?:5-21|12-1)-[0-9-]+$' }) }
    finally { $ubase.Dispose() }
    $profiles = @(Get-CimInstance -ClassName Win32_UserProfile -ErrorAction Stop | Where-Object { -not $_.Special -and $_.SID -match '^S-1-(?:5-21|12-1)-[0-9-]+$' })
    $allSids = @(@($profiles | ForEach-Object { $_.SID }) + $loadedSids | Sort-Object -Unique)
    $userTargets = @($allSids | ForEach-Object { [pscustomobject]@{Sid=$_; Loaded=($loadedSids -contains $_)} })
} catch { $userEnumerationError = $_.Exception.Message }

foreach ($control in $catalog) {
    try {
        switch ($control.Kind) {
            'Registry' {
                $isUser = @($control.Targets | Where-Object { $_.Hive -eq 'HKU' }).Count -gt 0
                $scopes = @([pscustomobject]@{Sid='Computer'; Loaded=$true})
                if ($isUser) {
                    if ($userEnumerationError) { Add-Result $control 'Error' -Notes $userEnumerationError -Scope 'User'; continue }
                    if ($userTargets.Count -eq 0) { Add-Result $control 'Unknown' -Notes 'No user profiles were available for assessment.' -Scope 'User'; continue }
                    $unloaded = @($userTargets | Where-Object { -not $_.Loaded })
                    if ($unloaded.Count -gt 0) {
                        Add-Result $control 'Unknown' ([string]$unloaded.Count+' unloaded profiles') 'Win32_UserProfile / HKU' 'Unloaded user profiles were not loaded or modified. Loaded profiles are assessed in separate rows.' 'UnloadedProfiles'
                    }
                    $scopes = @($userTargets | Where-Object { $_.Loaded })
                }
                foreach ($scope in $scopes) {
                    $states = New-Object 'System.Collections.Generic.List[string]'
                    $observed = New-Object 'System.Collections.Generic.List[string]'
                    $locators = New-Object 'System.Collections.Generic.List[string]'
                    $comments = New-Object 'System.Collections.Generic.List[string]'
                    if ($control.Notes) { $comments.Add($control.Notes) }
                    for ($i=0; $i -lt $control.Targets.Count; $i++) {
                        $target = $control.Targets[$i]
                        $key = $target.Key.Replace('[USER SID]', $scope.Sid)
                        $location = '{0}\{1}:{2}' -f $target.Hive, $key, $target.Name
                        $locators.Add($location)
                        try {
                            $ev = Get-RegistryEvidence $target.Hive $key $target.Name
                            $observed.Add(('{0}={1} ({2})' -f $target.Name, (Format-Evidence $ev.Value), $ev.Type))
                            if ($control.Operator -eq 'Absent') {
                                $states.Add($(if ($ev.Exists) { 'Fail' } else { 'Pass' }))
                            } elseif (-not $ev.Exists) {
                                $states.Add((Get-MissingRegistryStatus $control.Operator))
                                $comments.Add('Configured value is absent; the effective default and policy source need review.')
                            } elseif ($control.Operator -eq 'ManualText') {
                                $states.Add('ManualReview')
                            } elseif ($target.Types.Count -gt 0 -and $target.Types -notcontains $ev.Type) {
                                $states.Add('Fail')
                                $comments.Add(('Registry type must be {0}.' -f ($target.Types -join ' or ')))
                            } else {
                                $op = $control.Operator; $expected = @($control.Values)
                                if ($op -eq 'PerTarget') { $op = 'Equals'; $expected = @($control.Values[$i]) }
                                if (Test-Value $ev.Value $op $expected) { $states.Add('Pass') } else { $states.Add('Fail') }
                            }
                        } catch {
                            $states.Add('Error'); $observed.Add(('{0}=<unreadable>' -f $target.Name)); $comments.Add($_.Exception.Message)
                        }
                    }
                    $status = 'Pass'
                    foreach ($candidate in 'Error','Fail','Unknown','ManualReview') {
                        if ($states.Contains($candidate)) { $status=$candidate; break }
                    }
                    $comments.Add('Registry configuration evidence; operational enforcement and documented role exceptions require separate review.')
                    Add-Result $control $status ($observed -join '; ') ($locators -join '; ') (($comments | Select-Object -Unique) -join ' ') $scope.Sid
                }
            }
            'Rights' {
                if ($nativeError) { throw $nativeError }
                $actual = @([Windows11AuditR1.Native]::Rights($control.Locator))
                $rightNotes = New-Object 'System.Collections.Generic.List[string]'
                $expected = @()
                foreach ($name in @($control.Values)) {
                    try { $expected += (Resolve-PrincipalSid $name) }
                    catch {
                        # Service SIDs under RESTRICTED SERVICES only exist on newer Windows 11 builds.
                        if ($name -notlike 'RESTRICTED SERVICES\*') { throw }
                        $rightNotes.Add(('{0} does not exist on this build and was not expected.' -f $name))
                    }
                }
                $accepted = @()
                foreach ($option in @($control.Optional)) {
                    $conditionMet = $false
                    try { $conditionMet = Get-FeatureInstalled $option.When }
                    catch { $rightNotes.Add(('Could not determine whether {0} is installed: {1}' -f $option.When, $_.Exception.Message)) }
                    if (-not $conditionMet) { continue }
                    try {
                        $accepted += (Resolve-PrincipalSid $option.Name)
                        $rightNotes.Add(('{0} is accepted as an additional entry because {1} is installed.' -f $option.Name, $option.When))
                    } catch { $rightNotes.Add(('{0} could not be resolved on this system.' -f $option.Name)) }
                }
                $assessed = @($actual | Where-Object { $accepted -notcontains $_ })
                $ok = Test-Value $assessed $control.Operator $expected
                Add-Result $control $(if ($ok) { 'Pass' } else { 'Fail' }) (Format-Evidence $actual) ('LSA assigned SIDs: '+$control.Locator) ((@(('Expected SIDs: {0}. Compare any additional assignments with documented configuration exceptions.' -f ($expected -join ', '))) + @($rightNotes.ToArray())) -join ' ')
            }
            'Audit' {
                if ($nativeError) { throw $nativeError }
                $flags = [Windows11AuditR1.Native]::Audit($control.Locator)
                $actual = switch ($flags -band 3) { 0 {'No Auditing'} 1 {'Success'} 2 {'Failure'} 3 {'Success and Failure'} }
                $ok = Test-Value $flags $control.Operator @($control.Values)
                Add-Result $control $(if ($ok) { 'Pass' } else { 'Fail' }) ($actual+'; flags='+$flags) ('AuditQuerySystemPolicy '+$control.Locator) 'System subcategory policy; per-user audit exclusions and event generation are outside this check.'
            }
            'Service' {
                $serviceKey = 'SYSTEM\CurrentControlSet\Services\' + $control.Locator
                $location = 'HKLM\{0}:Start' -f $serviceKey
                if (-not (Test-RegistryKeyExists $serviceKey)) {
                    Add-Result $control 'Pass' 'Service not installed' $location 'The service registry key does not exist, so the service is not installed on this system.'
                    continue
                }
                $ev = Get-RegistryEvidence 'HKLM' $serviceKey 'Start'
                if (-not $ev.Exists) {
                    Add-Result $control 'Unknown' 'Start=<absent>' $location 'The service key exists but has no Start value; review the service registration.'
                    continue
                }
                $startName = switch ([string]$ev.Value) { '0' {'Boot'} '1' {'System'} '2' {'Automatic'} '3' {'Manual'} '4' {'Disabled'} default {'Unrecognised'} }
                $ok = ($ev.Type -eq 'DWord' -and (Test-Value $ev.Value 'Equals' @($control.Values)))
                Add-Result $control $(if ($ok) { 'Pass' } else { 'Fail' }) ('Start={0} ({1})' -f (Format-Evidence $ev.Value), $startName) $location 'Configured startup type from the registry; the current running state and trigger-start behaviour are outside this check.'
            }
            'RegistryList' {
                $listTarget = $control.Targets[0]
                $location = '{0}\{1}' -f $listTarget.Hive, $listTarget.Key
                $list = Get-RegistryKeyData $listTarget.Key
                if (-not $list.Exists) {
                    Add-Result $control 'Unknown' '<key absent>' $location 'Configured key is absent; the effective default and policy source need review.'
                    continue
                }
                $normalise = { param($Text) ([string]$Text).Trim().Trim('{', '}').ToLowerInvariant() }
                $have = @($list.Data | ForEach-Object { & $normalise $_ })
                $missing = @($control.Values | Where-Object { $have -notcontains (& $normalise $_) })
                $ok = ($missing.Count -eq 0)
                $listNote = if ($ok) { 'All expected entries are present; additional entries are permitted for this check.' } else { 'Missing entries: ' + ($missing -join ' | ') }
                Add-Result $control $(if ($ok) { 'Pass' } else { 'Fail' }) (Format-Evidence $list.Data) $location ($listNote + ' Registry configuration evidence; operational enforcement requires separate review.')
            }
            'Password' {
                if ($nativeError) { throw $nativeError }
                $isLockout = $control.Id.StartsWith('LOCKOUT_')
                $values = if ($isLockout) { $lockValues } else { $passwordValues }
                $readError = if ($isLockout) { $lockError } else { $passwordError }
                if ($readError) { throw $readError }
                $actual = $values[$control.Locator]
                $note = 'Local SAM policy; this does not assess domain or Microsoft Entra account policy or fine-grained password policies.'
                if ($control.Id -eq 'LOCKOUT_0008' -and [double]::IsInfinity($actual)) {
                    Add-Result $control 'ManualReview' 'Indefinite lockout' 'NetUserModalsGet level 3' ($note+' Review indefinite duration against the recommended setting and approved policy.')
                    continue
                }
                $ok = Test-Value $actual $control.Operator @($control.Values)
                if ($isLockout -and $lockValues['Threshold'] -eq 0) { $ok=$false; $note+=' Account lockout is disabled (threshold 0).' }
                if ($control.Id -eq 'LOCKOUT_0011' -and $actual -gt $lockValues['LockoutMinutes']) { $ok=$false; $note+=' Reset time exceeds account lockout duration.' }
                Add-Result $control $(if ($ok) { 'Pass' } else { 'Fail' }) ([string]$actual) ('NetUserModalsGet: '+$control.Locator) $note
            }
            { $_ -in 'Guest','Rename' } {
                if ($nativeError) { throw $nativeError }
                $rid = if ($control.Locator -eq 'RID 500') { 500 } else { 501 }
                $sid = [Windows11AuditR1.Native]::AccountDomainSid()+'-'+$rid
                $account = $null; $disabled = $false; $accountSource = ''
                if ($null -ne (Get-Command Get-LocalUser -ErrorAction SilentlyContinue)) {
                    $account = Get-LocalUser -SID $sid -ErrorAction Stop
                    $disabled = -not $account.Enabled
                    $accountSource = 'Get-LocalUser SID='+$sid
                } else {
                    $filter = "SID='$sid' AND LocalAccount=True"
                    $accounts = @(Get-CimInstance -ClassName Win32_UserAccount -Filter $filter -ErrorAction Stop)
                    if ($accounts.Count -ne 1) { throw "Could not uniquely read built-in account $sid." }
                    $account = $accounts[0]; $disabled = [bool]$account.Disabled
                    $accountSource = 'Win32_UserAccount '+$filter
                }
                if ($control.Kind -eq 'Guest') {
                    Add-Result $control $(if ($disabled) { 'Pass' } else { 'Fail' }) ('Disabled='+$disabled) $accountSource
                } else {
                    Add-Result $control 'ManualReview' $account.Name $accountSource $control.Notes
                }
            }
            'Manual' { Add-Result $control 'ManualReview' -Notes $control.Notes }
            default { throw ('Unsupported check kind: '+$control.Kind) }
        }
    } catch {
        Add-Result $control 'Error' -Evidence $control.Locator -Notes $_.Exception.Message
    }
}
$csvRows = foreach ($row in $rows) {
    $safe = [ordered]@{}
    foreach ($property in (ConvertTo-SpreadsheetRow $row).PSObject.Properties) {
        $safe[$property.Name] = ConvertTo-SafeCsvCell $property.Value
    }
    [pscustomobject]$safe
}
$stream = $null; $writer = $null
try {
    $stream = [IO.File]::Open($csvPath, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
    $writer = New-Object IO.StreamWriter ($stream, (New-Object Text.UTF8Encoding $true))
    $csvRows | ConvertTo-Csv -NoTypeInformation | ForEach-Object { $writer.WriteLine($_) }
    $writer.Flush()
} finally {
    if ($null -ne $writer) { $writer.Dispose() } elseif ($null -ne $stream) { $stream.Dispose() }
}
Write-Host ('Audit complete: {0}' -f $csvPath)
$rows | Group-Object Status | Sort-Object Name | ForEach-Object { Write-Host ('{0}: {1}' -f $_.Name, $_.Count) }
Write-Host 'Unknown, Error and ManualReview rows are unresolved; they are not passes.'

Write-Host 'Area results: Pass / (Pass + Fail), with each check counted once; unresolved results are excluded from this percentage.'
Get-AreaSummary @($rows.ToArray()) | ForEach-Object {
    $pct = if ($null -eq $_.AssessedPassPercent) { 'N/A' } else { '{0:N1}%' -f $_.AssessedPassPercent }
    Write-Host ('{0}: {1} ({2} pass, {3} fail; {4} unresolved, {5} excluded)' -f $_.Area, $pct, $_.Pass, $_.Fail, $_.Unresolved, $_.NotApplicable)
}
